import{_ as t}from"./chunks/gapnhau.CFKThRSD.js";import{_ as i,o as a,c as g,a1 as c}from"./chunks/framework.DK3UFCr3.js";const h="/40years/dangtrai.jpg",y=JSON.parse('{"title":"Những trang ký ức – 40 năm gặp lại","description":"","frontmatter":{"layout":"doc","hero":{"name":"PBC 86","text":"Hoi ngo 40 nam","tagline":"Lop C3","image":{"src":"/pbc.svg"},"actions":[{"theme":"brand","text":"Nguyen Chanh Minh","link":"/chanhminh"},{"theme":"alt","text":"Nguyen Van Tam","link":"/nvt"}]},"features":[{"title":"Feature A","details":"Lorem ipsum dolor sit amet, consectetur adipiscing elit"},{"title":"Feature B","details":"Lorem ipsum dolor sit amet, consectetur adipiscing elit"},{"title":"Feature C","details":"Lorem ipsum dolor sit amet, consectetur adipiscing elit"}]},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),e={name:"index.md"};function r(m,n,o,p,l,s){return a(),g("div",null,[...n[0]||(n[0]=[c('<h1 id="nhung-trang-ky-uc-–-40-nam-gap-lai" tabindex="-1">Những trang ký ức – 40 năm gặp lại <a class="header-anchor" href="#nhung-trang-ky-uc-–-40-nam-gap-lai" aria-label="Permalink to &quot;Những trang ký ức – 40 năm gặp lại&quot;">​</a></h1><hr><p>Sau 40 năm, chúng ta lại có dịp ngồi bên nhau, kể chuyện ngày xưa, nhắc tên những người bạn cũ và cùng lật lại những trang ký ức tưởng đã nằm yên đâu đó trong mỗi người.</p><p>Sau cuộc hội ngộ, những cảm xúc ấy vẫn tiếp tục được viết ra và chia sẻ rải rác trên Facebook, Zalo và nhiều nơi khác. Có những bài viết thật hay, những câu chuyện thật cảm động, những tấm ảnh tưởng như bình thường mà bỗng trở nên vô cùng quý giá khi nhìn lại sau 40 năm.</p><p>Trang web này được lập với mong muốn gom nhặt và lưu giữ những mảnh ký ức ấy — như một cuốn album chung của cả lớp, nơi những câu chuyện, bài viết, hình ảnh và kỷ niệm về một thời tuổi trẻ có thể được tìm lại bất cứ lúc nào.</p><p>Đây không phải là một trang web của riêng ai, mà là góc ký ức chung của chúng ta.</p><p><img src="'+t+'" alt="gap nhau"></p><p style="text-align:center;font-style:italic;">Dang gai</p><p>Vì vậy, rất mong các bạn cùng góp thêm cho trang những gì mình đang có: một bài viết đã đăng trên Facebook hay Zalo, một tấm ảnh cũ, một câu chuyện chưa kịp kể, một kỷ niệm về thầy cô, bạn bè, trường lớp… Hay đơn giản chỉ là một vài dòng cảm nghĩ sau ngày hội ngộ.</p><p><strong>Các bạn cứ mạnh dạn gửi về — bài dài hay ngắn, cũ hay mới, vui hay buồn đều được trân trọng.</strong> Mỗi đóng góp sẽ giúp trang web thêm phong phú, sinh động và quan trọng hơn, giúp những ký ức của chúng ta không bị trôi đi theo thời gian.</p><p>Để rồi nhiều năm nữa, khi ai đó trong chúng ta lại mở trang này, vẫn có thể mỉm cười và nói: <strong>“À, ngày ấy chúng mình đã từng như thế…”</strong></p><p><img src="'+h+'" alt="dang trai"></p><p style="text-align:center;font-style:italic;">Dang trai</p>',13)])])}const k=i(e,[["render",r]]);export{y as __pageData,k as default};
